begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
delete from public.company_profiles;
create temp table company_audit_baseline as select count(*)::int as n from public.audit_logs where table_name='company_profiles';
insert into auth.users(id,instance_id,aud,role,email) select ('ab210000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','company-'||n||'@example.invalid' from generate_series(1,4)n;
insert into public.staff_users(user_id,role) values('ab210000-0000-4000-8000-000000000001','admin'),('ab210000-0000-4000-8000-000000000002','office'),('ab210000-0000-4000-8000-000000000003','technician');
create function pg_temp.fields() returns jsonb language sql as $$select '{"companyName":"Firma testowa","companyAddress":"Adres","taxId":"","email":"biuro@example.invalid","phone":"","website":"","intro":"Wprowadzenie","paymentTerms":"Zaliczka 20%","completionTerms":"Uzgodniony termin","exclusions":"","note":"","validityDays":30,"logoPng":"data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAYAAABytg0kAAAAEUlEQVR4nGP46834H4QZYAwAUroJIRVPF+oAAAAASUVORK5CYII="}'::jsonb$$;
create function pg_temp.document() returns jsonb language sql as $$select (pg_temp.fields()-'validityDays')||'{"issuedOn":"2026-11-03","validUntil":"2026-12-03"}'$$;
insert into public.customers(id,name) values('cc210000-0000-4000-8000-000000000001','Klient SQLTEST profilu');
set local role authenticated;
select set_config('request.jwt.claim.sub','ab210000-0000-4000-8000-000000000001',true);
select is(public.company_profile(),null::jsonb,'No default profile before first save');
select throws_ok($$select public.save_company_profile(null,pg_temp.fields()||'{"issuedOn":"2026-11-03"}')$$,'22023',null,'Dates cannot be saved as global defaults');
select throws_ok($$select public.save_company_profile(null,pg_temp.fields()||'{"validityDays":0}')$$,'22023',null,'Zero validity rejected');
select throws_ok($$select public.save_company_profile(null,pg_temp.fields()||'{"validityDays":366}')$$,'22023',null,'Overlong validity rejected');
select throws_ok($$select public.save_company_profile(null,pg_temp.fields()||'{"companyName":""}')$$,'22023',null,'Empty company rejected');
select throws_ok($$select public.save_company_profile(null,pg_temp.fields()||'{"logoPng":"https://example.invalid/logo"}')$$,'22023',null,'Remote logos rejected');
select throws_ok($$select public.save_company_profile(null,pg_temp.fields()||'{"logoPng":"data:image/png;base64,aGVsbG8="}')$$,'22023',null,'Invalid PNG header rejected');
select throws_ok($$select public.save_company_profile(null,pg_temp.fields()||'{"secret":true}')$$,'22023',null,'Extra keys rejected');
select is(public.save_company_profile(null,pg_temp.fields())->>'version','0','Admin saves initial profile');
select is(public.save_company_profile(null,pg_temp.fields())->>'version','0','Identical initial retry safe');
select is(public.company_profile()->'data'->>'validityDays','30','Validity retained');
select is(public.company_profile()->'data'->>'logoPng','data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAYAAABytg0kAAAAEUlEQVR4nGP46834H4QZYAwAUroJIRVPF+oAAAAASUVORK5CYII=','Logo retained');
select public.save_offer('ef210000-0000-4000-8000-000000000001','{"customerId":"cc210000-0000-4000-8000-000000000001","locationId":null,"title":"SQLTEST profile","workType":"split","technical":{"lengthMills":0,"laborMills":0,"travelMills":0},"mainVariantId":"dd210000-0000-4000-8000-000000000001","archived":false,"variants":[{"id":"dd210000-0000-4000-8000-000000000001","name":"Standard","internalNote":"","customerNote":"","targetMarginBasisPoints":3000,"overrideNetCents":null,"lines":[{"id":"df210000-0000-4000-8000-000000000001","catalogId":null,"code":"","name":"Praca","description":"","category":"service","unit":"hour","quantityMills":1000,"costCents":100,"saleCents":200,"vatBasisPoints":2300,"discountBasisPoints":0}]}]}',null);
select is(public.save_offer_document('ef210000-0000-4000-8000-000000000001',pg_temp.document(),null,0)->'data'->>'logoPng','data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAYAAABytg0kAAAAEUlEQVR4nGP46834H4QZYAwAUroJIRVPF+oAAAAASUVORK5CYII=','Document snapshots own logo');
select is(public.save_company_profile(0,pg_temp.fields()||'{"companyName":"Nowa firma"}')->>'version','1','Profile advances version');
select is(public.save_company_profile(0,pg_temp.fields()||'{"companyName":"Nowa firma"}')->>'version','1','Update retry does not add version');
select throws_ok($$select public.save_company_profile(0,pg_temp.fields()||'{"companyName":"Stara sesja"}')$$,'40001',null,'Stale edit rejected');
select is(public.offer_document_context('ef210000-0000-4000-8000-000000000001')->'document'->'data'->>'companyName','Firma testowa','Profile edit does not alter saved document');
select is(public.offer_document_context('ef210000-0000-4000-8000-000000000001')->'document'->>'version','0','Profile edit does not alter document version');
select is(public.save_offer_document('ef210000-0000-4000-8000-000000000001',pg_temp.document()-'logoPng',0,0)->'data'->>'logoPng',null::text,'Legacy document without logo remains valid');
reset role;
select is((select count(*)::int from public.company_profiles),1,'Only one company profile');
select is((select count(*)::int from public.audit_logs where table_name='company_profiles'),(select n+2 from company_audit_baseline),'Audit only creation and actual change');
select ok(not exists(select 1 from public.audit_logs where table_name='company_profiles' and (new_data?'data' or old_data?'data')),'Audit excludes duplicate logo blobs');
set local role authenticated;
select set_config('request.jwt.claim.sub','ab210000-0000-4000-8000-000000000002',true);
select is(public.company_profile()->>'version','1','Office reads profile');
select throws_ok($$select public.save_company_profile(1,pg_temp.fields())$$,'42501',null,'Office cannot change global defaults');
select set_config('request.jwt.claim.sub','ab210000-0000-4000-8000-000000000003',true);
select throws_ok($$select public.company_profile()$$,'42501',null,'Technician denied profile');
select throws_ok($$select public.save_company_profile(1,pg_temp.fields())$$,'42501',null,'Technician denied write');
select set_config('request.jwt.claim.sub','ab210000-0000-4000-8000-000000000004',true);
select throws_ok($$select public.company_profile()$$,'42501',null,'No staff access denied');
select throws_ok($$select * from public.company_profiles$$,'42501',null,'Direct table access denied');
reset role;
insert into public.account_access(user_id,blocked) values('ab210000-0000-4000-8000-000000000001',true);
set local role authenticated;
select set_config('request.jwt.claim.sub','ab210000-0000-4000-8000-000000000001',true);
select throws_ok($$select public.save_company_profile(1,pg_temp.fields())$$,'42501',null,'Blocked administrator denied');
reset role;
set local role anon;
select throws_ok($$select public.company_profile()$$,'42501',null,'Anonymous denied');
select * from finish();
rollback;
